 function know(){if(completing)return;if(practice){shortcut=true;resetAttempt()}}
 function restart(){if(completing)return;resetAttempt();result=false}
 async function remove(item:Item){await action('remove',async()=>{const removed={...item,deleted:true,updatedAt:Date.now()};data.items=data.items.map(entry=>entry.id===item.id?removed:entry);await save();removeTarget=null;undoItem=removed;clearTimeout(undoTimer);undoTimer=setTimeout(()=>{if(undoItem?.id===item.id)undoItem=null},3000)})}

 async function undo(){if(!undoItem)return;await action('undo',async()=>{const revived={...undoItem!,deleted:false,updatedAt:Date.now()};const proposed=data.items.map(item=>item.id===revived.id?revived:item);assertEsvLimit(proposed);data.items=proposed;undoItem=null;await save()})}
 function passageItems(){if(passageMode==='separate'||found.length<2)return found;const groups=passageMode==='chunks'?Array.from({length:Math.ceil(found.length/4)},(_,i)=>found.slice(i*4,i*4+4)):[found];return groups.map(group=>({...group[0],id:group[0].id+'--'+group.at(-1).id,title:group[0].title+'–'+(group[0].title.split(':')[0]===group.at(-1).title.split(':')[0]?group.at(-1).title.split(':').at(-1):group.at(-1).title.split(' ').at(-1)),text:group.map(i=>i.text).join(' ')}))}

</script>
{#snippet emailFeedback(control:string)}
 {#if emailError&&emailErrorControl===control}<p role="alert">{emailError}</p>{/if}
{/snippet}
{#snippet emailForm()}
 <form class="stack" onsubmit={(event)=>{event.preventDefault();void (emailSent?verifyEmail():sendEmail())}} aria-label={account?ui.addEmail:ui.emailSignin}>
 <label>{ui.emailAddress}<input type="email" autocomplete="email" required maxlength={254} bind:value={emailAddress} disabled={emailSent||!!emailBusy||!!codeBusy}/></label>
 {#if emailStatus}<p role="status">{emailStatus}</p>{/if}
 {#if emailSent}
 <label>{ui.emailCode}<input type="text" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength={6} value={emailCode} oninput={codeInput} disabled={!!codeBusy||!!emailBusy}/></label>
 <Button type="submit" disabled={!!codeBusy||!!emailBusy||emailCode.length!==6}>{emailBusy==='verify'?ui.verifyingCode:ui.verifyCode}</Button>
 {@render emailFeedback('verify')}
 <Button secondary onclick={()=>void sendEmail()} disabled={!!codeBusy||!!emailBusy||resendSeconds>0}>{emailBusy==='send'?ui.sendingCode:resendSeconds?ui.resendCountdown(resendSeconds):ui.resendCode}</Button>
 {@render emailFeedback('send')}
 <Button secondary onclick={editEmail} disabled={!!codeBusy||!!emailBusy}>{ui.changeEmail}</Button>
 {:else}
 <Button type="submit" disabled={!!codeBusy||!!emailBusy||resendSeconds>0}>{emailBusy==='send'?ui.sendingCode:resendSeconds?ui.resendCountdown(resendSeconds):ui.sendCode}</Button>
 {@render emailFeedback('send')}
 {/if}
 </form>
{/snippet}
{#snippet signInCodeControls()}
 {#if account}
 <section class="signin-code-settings stack" aria-label={ui.codeAccount.title}>
 <h4>{ui.codeAccount.title}</h4>
 {#if account.hasCode}
 {#if deviceCode&&deviceCode.uid===account.id&&deviceCode.revision===account.codeRevision}
 <Button secondary ariaExpanded={codeRevealed} ariaControls="saved-signin-code" onclick={()=>codeRevealed=!codeRevealed}>{codeRevealed?ui.codeAccount.hide:ui.codeAccount.reveal}</Button>
 {#if codeRevealed}<p id="saved-signin-code" class="signin-code-value" data-private>{deviceCode.code}</p>{@render codeSaveActions()}{/if}
 {:else}<p>{ui.codeAccount.missing}</p>{/if}
 <small>{ui.codeAccount.deviceOnly}</small>
 <Button secondary disabled={!!codeBusy||!!emailBusy} onclick={()=>{clearAction('code-regenerate');codeConfirm='regenerate'}}>{ui.codeAccount.regenerate}</Button>
 {#if account.hasEmail||account.hasGoogle}<Button secondary disabled={!!codeBusy||!!emailBusy} onclick={()=>{clearAction('code-remove');codeConfirm='remove'}}>{ui.codeAccount.remove}</Button>{/if}
 {:else}<Button secondary disabled={!!codeBusy||!!emailBusy} onclick={()=>void codeAccountAction('regenerate')}>{ui.codeAccount.add}</Button><ActionFeedback note={actionNotes['code-regenerate']}/>{/if}
 <ActionFeedback note={actionNotes['code-remove']}/>
 {#if account.hasCode&&!account.hasEmail&&!account.hasGoogle&&codeReminder<=Date.now()}<div class="code-backup-hint stack"><p>{ui.codeAccount.backup}</p><button class="text-button" onclick={forgetCodeBackupReminder}>{ui.codeAccount.dismiss}</button></div>{/if}
 </section>
 {:else}
 <div class="signin-code-entry stack">
 <Button secondary disabled={!!codeBusy||!!emailBusy} onclick={()=>void codeAccountAction('create')}>{codeBusy==='create'?ui.codeAccount.creating:ui.codeAccount.create}</Button><ActionFeedback note={actionNotes['code-create']}/>
 <form class="stack" aria-label={ui.codeAccount.signin} onsubmit={event=>{event.preventDefault();void codeAccountAction('signin')}}>
 <label>{ui.codeAccount.field}<input type="text" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength={90} bind:value={codeEntry} placeholder={ui.codeAccount.placeholder} disabled={!!codeBusy||!!emailBusy}/></label>
 <Button secondary type="submit" disabled={!!codeBusy||!!emailBusy||!codeEntry.trim()}>{codeBusy==='signin'?ui.codeAccount.signingIn:ui.codeAccount.signin}</Button><ActionFeedback note={actionNotes['code-signin']}/>
 </form></div>
 {/if}
{/snippet}
{#snippet codeSignoutReminder()}
 {#if account?.hasCode&&!account?.hasEmail&&!account?.hasGoogle}<p>{ui.codeAccount.signoutWarning}</p>{#if deviceCode}<Button secondary ariaExpanded={codeRevealed} ariaControls="signout-signin-code" onclick={()=>codeRevealed=!codeRevealed}>{codeRevealed?ui.codeAccount.hide:ui.codeAccount.reveal}</Button>{#if codeRevealed}<p id="signout-signin-code" class="signin-code-value" data-private>{deviceCode.code}</p><Button secondary onclick={()=>void copyAccountCode()}>{ui.codeAccount.copy}</Button><ActionFeedback note={actionNotes['code-copy']}/>{/if}{/if}{/if}
{/snippet}
{#snippet codeSaveActions()}
 <div class="code-save-actions"><Button secondary onclick={()=>void copyAccountCode()}>{ui.codeAccount.copy}</Button><Button secondary onclick={()=>void shareAccountCode()}>{ui.codeAccount.share}</Button><Button secondary onclick={printAccountCode}>{ui.codeAccount.print}</Button></div>
 <ActionFeedback note={actionNotes['code-copy']}/><ActionFeedback note={actionNotes['code-share']}/>
{/snippet}
{#snippet translationPicker()}<label class="translation-picker"><span class="sr-only">{ui.defaultTranslation}</span><select aria-label={ui.defaultTranslation} bind:value={data.settings.defaultTranslation} onchange={changeTranslation}>{#each passageTranslations as value}<option>{value}</option>{/each}</select></label><ActionFeedback note={actionNotes.translation}/>{/snippet}
{#if printableCode}<article class="signin-print-card"><h1>{ui.codeAccount.printTitle}</h1><p class="signin-code-value">{printableCode}</p><p>{ui.codeAccount.printHelp}</p><p>incord.jesklabs.com</p></article>{/if}
<svelte:window onkeydown={physical}/>
<main use:hapticOverlay={{enabled:!!data.settings.haptics}} class:practicing={!!practice&&!learned}>
{#if !ready}<section class="empty"><h1>{ui.appName}</h1><p>{ui.loadingBody}</p></section>
{:else if oauthRoute&&identityVerified&&account}
 <section class="page mcp-consent stack" aria-labelledby="consent-title">
 <small>{ui.appName}</small><h1 id="consent-title">{ui.mcpConsentTitle}</h1>
 {#if consent}
 <p>{ui.mcpConsentIntro(consent.clientName)}</p>
 <section class="settings-group"><h2 class="mcp-client-name">{consent.clientName}</h2>{#if consent.clientDomain}<small>{consent.clientDomain}</small>{/if}<p>{ui.mcpUnverified}</p>
 <h3>{ui.mcpPermissions}</h3><ul class="mcp-scopes">{#each consent.scope as scope}<li>{ui.mcpScope(scope)}</li>{/each}</ul>
 <p>{ui.mcpRedirect(consent.redirectHost)}</p>{#if consent.redirectIsLoopback}<p class="notice">{ui.mcpLoopback}</p>{/if}</section>
 <p>{ui.mcpRevokeHint}</p>
 <form class="stack" onsubmit={(event)=>{event.preventDefault();void decideConsent('approve')}} aria-label={ui.mcpApprove}><Button type="submit" disabled={consentBusy}>{consentBusy?ui.mcpWorking:ui.mcpApprove}</Button><ActionFeedback note={consentDecision==='approve'&&consentError?{text:consentError,error:true}:undefined}/></form>
 <form onsubmit={(event)=>{event.preventDefault();void decideConsent('deny')}} aria-label={ui.mcpDeny}><Button secondary type="submit" disabled={consentBusy}>{ui.mcpDeny}</Button><ActionFeedback note={consentDecision==='deny'&&consentError?{text:consentError,error:true}:undefined}/></form>
 {:else if consentBusy}<p role="status">{ui.mcpLoadingConsent}</p>{/if}
 {#if consentError&&!consentDecision}<p class="notice error" role="alert">{consentError}</p>{#if !consent}<Button secondary disabled={consentBusy} onclick={()=>void loadConsent()}>{ui.mcpRetry}</Button>{/if}{/if}
 </section>
{:else if practice}
 {#if loadingPassage}<p role="status">{ui.loadingBody}</p>{/if}
 {#if learned}<section class="learned"><svg class="learned-check" viewBox="0 0 48 48" aria-hidden="true"><path d="M10 25l9 9L39 14"/></svg><h1>{review?ui.reviewed:ui.learned}</h1><article class="keepsake" style:background={collectionColor(practice)}><p>{practice.text}</p><footer><b>{practice.title}</b>{#if practice.translation==='ESV'}<EsvAttribution translation={practice.translation}/>{:else}<small class:translation-badge={!!practice.translation}>{sourceLabel(practice)}</small>{/if}</footer></article>{#if nextDue}<small>{ui.nextReviewPrefix}{nextDue}</small>{/if}<Button onclick={loadNext}>{session.length?ui.nextItem:ui.backToToday}</Button><Button secondary onclick={()=>{learned=false;rehearsal=true;review=false;restart()}}>{ui.practiceOnceMore}</Button></section>
 {:else}<section class="practice" onpointerdown={unlockPractice} ontouchstart={unlockPractice} onpointerup={unlockPractice} ontouchend={unlockPractice} onclick={unlockPractice} bind:this={practiceRegion} tabindex="-1" aria-label={ui.practiceRegionLabel} inert={result||confirmLeavePractice} aria-hidden={result||confirmLeavePractice}><header><button class="icon" aria-label={ui.closePractice} onclick={requestClosePractice}>×</button><StepDots step={attemptStep}/>{#if attemptStep===1&&!review}<Button secondary onclick={know}>{ui.knowThis}</Button>{:else}<button class="icon" aria-label={ui.restartStep} onclick={restart}>↻</button>{/if}</header><div class="prompt" class:collapsed={position>0&&!titleExpanded} class:expanded={titleExpanded}><small>{review?ui.reviewBlankRecall:ui.stepPrefix+attemptStep+ui.stepOfFour+[ui.empty,ui.readAlong,ui.fewWordsHidden,ui.almostFromMemory,ui.fromMemory][attemptStep]}</small><h1 data-title={practice.title}><div class="prompt-title-scroll"><button class="prompt-title" aria-expanded={titleExpanded} onclick={()=>titleExpanded=!titleExpanded}>{practice.title}</button></div></h1>{#if practice.translation==='ESV'}<EsvAttribution translation={practice.translation}/>{:else}<small class:translation-badge={!!practice.translation}>{sourceLabel(practice)}</small>{/if}</div><div class="progress"><i style:width={position/words.length*100+ui.percent}></i></div><ActionFeedback note={actionNotes.practice}/><div class="practice-feedback">{#if showPracticeInstruction}<small class="practice-instruction">{ui.typeFirstLetters}</small>{:else}<span class="practice-letter-slot" aria-hidden="true">{#if typedLetter}<span class="typed-letter" class:slip={typedSlip}>{typedLetter}</span>{/if}</span>{#if tapUndo}<button class="text-button practice-undo" onclick={undoTap}>{ui.undo}</button>{/if}{/if}</div><VerseText {words} {mask} text={practice.text} index={position} slipped={visualSlips}/><div class="sr-only" aria-live="polite" aria-atomic="true">{practiceAnnouncement||ui.practicePosition(position,words.length)}</div>{#key practice.id}<Keyboard hasNumbers={words.some(word=>/^\d/.test(word))} onkey={key} disabled={result||completing}/>{/key}</section>{/if}
 {#if result}<Sheet title={resultTitle} close={continueResult}><p>{resultDetail}</p><div class="practice-result"><Button onclick={continueResult}>{review&&!resultLearned?ui.relearnNow:rehearsal?ui.done:resultLearned?ui.finish:ui.continue}</Button><Button secondary onclick={()=>{practice=null;result=false}}>{review&&!resultLearned?ui.later:ui.closePractice}</Button></div></Sheet>{/if}
{:else}
 <section class="page" class:has-toast={!!undoItem} class:account={tab===ui.account}>
 <header class:collection-header={!!detail}>{#if !detail}<div><h1>{tab===ui.account?ui.accountTitle:tab===ui.gallery?ui.components:tab}</h1>{#if tab===ui.today}<p>{new Date().toLocaleDateString("en-US",{weekday:"long",month:"long",day:"numeric"})}</p>{/if}</div>{/if}<button class="icon" aria-label={detail?ui.backToLibrary:ui.accountSettings} onclick={()=>detail?openCollection(''):navigate(ui.account)}>{#if detail}{ui.backGlyph}{:else if data.settings.name.trim()}{data.settings.name.trim().slice(0,1).toUpperCase()}{:else}<svg class="person" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/></svg>{/if}</button></header>
 {#if loadingPassage&&tab!==ui.discover}<p role="status">{ui.loadingBody}</p>{/if}{#if error}<div class="notice error" role="alert">{error}</div>{/if}{#if message}<div class="notice" role="status">{message}</div>{/if}
 {#if tab===ui.today}
 <div class="rhythm"><div><b>{weekCount}{ui.of}{data.settings.goal}{ui.thisWeekSuffix}</b></div><WeekDots days={data.settings.days}/></div>
 {#if due.length}<div class="hero"><div><b>{practiceCount(due.length)}</b><small>{minutes(estimatedMinutes)}</small></div><Button onclick={()=>begin(due)}>{ui.begin}</Button></div><h3 class="section-title">{ui.forToday}</h3><List>{#each due as item}<Row title={item.title} translation={item.translation} subtitle={`${item.learned?ui.review:item.step===1?ui.new:ui.learningStep(item.step)}${item.translation?ui.empty:` · ${sourceLabel(item)}`}`} onclick={()=>begin([item])}><StepDots step={item.learned?5:item.step}/></Row><ActionFeedback note={actionNotes['practice-load-'+item.id]}/>{/each}</List>
 {:else}<div class="empty"><div class="heart">♡</div><h2>{live.length?ui.doneForToday:ui.noItemsYet}</h2>{#if !live.length}<p>{ui.addCollection}</p>{/if}<Button onclick={()=>navigate(live.length?ui.library:ui.discover)}>{live.length?ui.visitLibrary:ui.findSomething}</Button></div>{/if}
 {#if groupAttention&&(groupAttention.pendingRequests||prayerAttention||groupAttention.goalsNearlyDone)}<button class="text-button group-attention" aria-labelledby="group-attention-text" onclick={openGroupAttention}><span aria-hidden="true">{groupAttention.pendingRequests?'◌':prayerAttention?'♡':'◉'}</span><span id="group-attention-text">{groupAttention.pendingRequests?ui.groups.attentionPending(groupAttention.pendingRequests):prayerAttention?ui.groups.attentionPrayer:ui.groups.attentionGoal}</span><span aria-hidden="true">›</span></button>{/if}
 {:else if tab===ui.groups.heading}
 {#key account?.id||'signed-out'}<Groups account={identityVerified?account:null} settings={data.settings} onSync={sync} onChooseGoal={chooseGroupGoal} onSignIn={signInForGroups} pendingCode={pendingGroupCode} onJoined={joinedGroup} {initialGroupId} onSelect={id=>initialGroupId=id} onAttention={setGroupAttention} onDialogChange={close=>groupDialogClose=close}/>{/key}
 {:else if tab===ui.library}
 {#if detail}<Cover title={collectionTitle(detail)} subtitle={plural(detailItems.length,"item")} color={starters.findIndex((s:any)=>s.id===detail)} compact/><div class="section-title"><h3>{ui.yourItems}</h3><button class="text-button" onclick={()=>{const target=detail;openDiscoverAdd();addTarget=target}}>{ui.addItems}</button></div><List>{#each detailItems as item}<Row title={item.title} subtitle={item.learned?ui.reviewDate(item.due):ui.stepPrefix+item.step} translation={item.translation} onclick={()=>begin([item])}><StepDots step={item.learned?5:item.step}/>{#snippet trailing()}<button class="text-button item-menu" aria-label={ui.optionsPrefix+item.title} onclick={()=>{clearAction('remove');removeTarget=item}}>…</button>{/snippet}</Row><ActionFeedback note={actionNotes['practice-load-'+item.id]}/>{#if !item.learned&&!due.some(i=>i.id===item.id)}<button class="text-button" onclick={()=>begin([item])}>{ui.startEarly}</button>{/if}{/each}</List>{#if detailItems.length}<div class="collection-practice"><Button onclick={()=>begin(detailItems)}>{ui.startPractice}</Button></div>{:else}<p>{ui.nothingHere}</p>{/if}
 {:else}<div class="section-title"><h3>{ui.yours}</h3><button class="text-button" onclick={openDiscoverAdd}>{ui.addShortcut}</button></div><List>{#each [...new Set(live.map(i=>i.collection))] as id}{@const items=live.filter(i=>i.collection===id)}<Row title={collectionTitle(id)} subtitle={items.filter(i=>i.learned).length+ui.of+items.length+ui.learnedSuffix} onclick={()=>openCollection(id)}><ProgressPie percent={items.filter(i=>i.learned).length/items.length*100}/></Row>{/each}</List>{#if !live.length}<div class="library-empty"><p>{ui.libraryEmpty}</p><Button onclick={()=>navigate(ui.discover)}>{ui.findSomething}</Button></div>{/if}{/if}
 {:else if tab===ui.discover}
 {#if goalTarget}<section class="notice stack" aria-label={ui.groupGoalChoose}><h2>{ui.groupGoalChoose}</h2><p>{ui.groupGoalHelp}</p><Button secondary onclick={()=>{goalTarget='';groupGoalError='';navigate(ui.groups.heading)}}>{ui.cancel}</Button></section>{/if}
 <div class="stack"><section aria-labelledby="featured-heading"><h2 id="featured-heading">{ui.startHere}</h2><div class="covers featured-cards"><div class="discovery-choice"><Cover title={ui.gospelTitle} subtitle={ui.gospelFeaturedDetail} translation={data.settings.defaultTranslation} color={0} onclick={()=>void previewFeatured('gospel')}/><ActionFeedback note={actionNotes['featured-gospel']}/></div><div class="discovery-choice"><Cover title="Psalm 23" subtitle={ui.psalmFeaturedDetail} translation={data.settings.defaultTranslation} color={1} onclick={()=>void previewFeatured('psalm23')}/><ActionFeedback note={actionNotes['featured-psalm23']}/></div><div class="discovery-choice"><Cover title="Westminster Shorter Catechism" subtitle={ui.wscFeaturedDetail} color={2} onclick={()=>void previewFeatured('wsc-start')}/><ActionFeedback note={actionNotes['featured-wsc-start']}/></div></div></section>
 <div class="discover-filters" aria-label={ui.discoverCategories}>{#each discoverFilters.filter(filter=>!goalTarget||filter!==ui.addYourOwn) as filter}<button class="text-button" class:active={discoverFilter===filter} aria-pressed={discoverFilter===filter} onclick={()=>filterDiscover(filter)}>{filter}</button>{/each}</div>
 {#if discoverFilter===ui.addYourOwn}<div class="discover-section-heading"><h2>{ui.addYourOwn}</h2>{@render translationPicker()}</div><div class="segments" aria-label={ui.contentType}>{#each [[ui.verseMode,ui.verses],[ui.ownMode,ui.yourText]] as [id,label]}<button class="segment" class:active={addMode===id} aria-pressed={addMode===id} onclick={()=>{clearPreviewNotes();passageRequest++;loadingPassage=false;addMode=id;selectedDoc='';found=[];clearAction('find');clearAction('own');clearAction('add')}}>{label}</button>{/each}</div>
 {#if addMode===ui.verseMode}<label>{ui.bibleReference}<input bind:value={reference} placeholder={ui.referencePlaceholder} onkeydown={e=>{if(e.key===ui.enterKey)void search()}}/></label><Button onclick={()=>void search()} disabled={busy||!reference.trim()}>{ui.findVerses}</Button><ActionFeedback note={actionNotes.find}/>{#if found.length}<div class="passage-actions">{#if data.settings.defaultTranslation!==incord.esv}<div class="segments passage-segments" aria-label={ui.passageMode}>{#each [['passage',ui.onePassage],['separate',ui.separateVerses],['chunks',ui.chunks]] as [mode,label]}<button class="segment" class:active={passageMode===mode} aria-pressed={passageMode===mode} onclick={()=>passageMode=mode}>{label}</button>{/each}</div>{/if}<Button onclick={()=>void add(passageItems(),undefined,false,tokenize(found.map(i=>i.text).join(' ')).length>500)}>{ui.addToLibrary}</Button><ActionFeedback note={actionNotes.add}/></div><List>{#each found as item}<Row title={item.title} subtitle={item.text} translation={item.translation} onclick={item.translation===incord.esv?()=>void previewFound(item):undefined}/><ActionFeedback note={actionNotes['found-'+item.id]}/>{/each}</List>{/if}{#if data.settings.defaultTranslation!==incord.esv}<small>{ui.publicDomainNotice}</small>{/if}
 {:else if addMode===ui.ownMode}<label>{ui.titleOrQuestion}<input bind:value={customTitle} maxlength={200}/></label><label>{ui.textToRemember}<textarea bind:value={customText} maxlength={10000}></textarea></label><p>{ui.privateTextNotice}</p><Button onclick={()=>void own()}>{ui.addYourText}</Button><ActionFeedback note={actionNotes.own}/>
 {/if}{/if}

 {#if discoverFilter===ui.topics}<section aria-labelledby="topics-heading"><div class="discover-section-heading"><h2 id="topics-heading">{ui.topics}</h2>{@render translationPicker()}</div><div class="topic-cards passage-cards">{#each topics as topic,i}<div class="discovery-choice"><Cover title={topic.title} subtitle={`${topic.verseCount} verses · ${topic.description}`} translation={data.settings.defaultTranslation} color={i} onclick={()=>void previewTopic(topic.id)}/><ActionFeedback note={actionNotes['topic-'+topic.id]}/></div>{/each}</div></section>{/if}
 {#if discoverFilter===ui.passages}<section aria-labelledby="passages-heading"><div class="discover-section-heading"><h2 id="passages-heading">{ui.passages}</h2>{@render translationPicker()}</div><p>{ui.passageDetail}</p><div class="passage-cards">{#each passages as passage,i}<div class="scripture-card"><Cover title={passage.reference} subtitle={`${passage.verseCount} verses · ${passage.title}`} color={i} translation={data.settings.defaultTranslation} onclick={()=>{if(!busy)void previewPassage(passage.id)}}/><ActionFeedback note={actionNotes['passage-'+passage.id]}/></div>{/each}</div></section>{/if}
 {#if discoverFilter===ui.catechismsAndCreeds}<section aria-labelledby="documents-heading"><h2 id="documents-heading" class="section-title">{ui.catechismsAndCreeds}</h2><div class="document-cards passage-cards">{#each documents as doc,i}<Cover title={doc.title} subtitle={documentSubtitle(doc)} color={i} onclick={()=>{selectedDoc=doc.id;void tick().then(()=>document.getElementById('document-browser')?.scrollIntoView({block:'start'}))}}/>{/each}</div>{#if selectedDoc}{@const doc=documents.find((d:any)=>d.id===selectedDoc)}{#if doc}{#if goalTarget}<div id="document-browser"><header class="document-intro"><h2>{doc.title}</h2><p>{doc.subtitle}</p>{#if doc.description}<p>{doc.description}</p>{/if}</header><form class="stack" aria-label={ui.groupGoalChoose} onsubmit={event=>{event.preventDefault();void setGroupGoal({kind:'document',id:doc.id,translation:data.settings.defaultTranslation||'BSB',start:Number(groupGoalStart),end:Number(groupGoalEnd)})}}><label>{ui.groupGoalStart}<input type="number" min="1" max={doc.questionCount||Math.max(...doc.items.map(item=>item.number||1))} bind:value={groupGoalStart} required/></label><label>{ui.groupGoalEnd}<input type="number" min={groupGoalStart} max={doc.questionCount||Math.max(...doc.items.map(item=>item.number||1))} bind:value={groupGoalEnd} required/></label><Button type="submit" disabled={groupGoalBusy}>{groupGoalBusy?ui.groupGoalSaving:ui.groupGoalUse}</Button>{#if groupGoalError}<p role="alert">{groupGoalError}</p>{/if}</form></div>{:else}{#key doc.id}<DocumentBrowser document={doc} {live} add={addChecked}/>{/key}{/if}{/if}{/if}</section>{/if}</div>
 {:else if tab===ui.account}
 <div class="stack">{#if pendingGroupCode&&!account}<section class="notice stack"><h2>{ui.groupInviteSignin}</h2><p>{ui.groupInviteSigninHelp}</p></section>{/if}{#if oauthRoute}<section class="notice stack"><h2>{ui.mcpSigninTitle}</h2><p>{ui.mcpSigninDetail}</p>{#if consentError}<p role="alert">{consentError}</p>{/if}</section>{/if}<section class="settings-group" aria-labelledby="account-heading"><h3 id="account-heading">{ui.yourAccount}</h3>{#if account}<p>{ui.signedIn}</p>{#if mergePrompt&&mergeDismissed}<Button secondary onclick={()=>mergeDismissed=false}>{ui.reviewDeviceItems}</Button>{/if}{#if config.email&&!account.hasEmail}{#if !emailOpen}<Button secondary onclick={()=>{emailOpen=true;editEmail()}}>{ui.addEmail}</Button>{:else}{@render emailForm()}{/if}{/if}{#if emailStatus&&!emailOpen}<p role="status">{emailStatus}</p>{/if}{#if (config.googleEnabled??config.google)&&!account.hasGoogle}<Button secondary onclick={()=>googleSignin(true)}>{ui.codeAccount.addGoogle}</Button>{/if}{#if googleLinkError}<p role="alert">{googleLinkError}</p>{/if}{@render signInCodeControls()}{#if !online}<small>{ui.offlineSync}</small>{/if}<Button secondary onclick={()=>{clearAction('signout');confirmSignout=true}}>{ui.signOut}</Button><Button secondary onclick={()=>{clearAction('signout-everywhere');confirmEverywhere=true}}>{ui.signoutEverywhere}</Button>{:else}<p>{ui.localAccountNotice}</p><Button disabled={!!emailBusy||!!codeBusy||jlBusy} onclick={primarySignin}>{ui.jesklabs.signIn}</Button>{#if jlError}<p role="alert">{jlError}</p>{/if}{#if config.googleEnabled??config.google}<Button disabled={!!emailBusy||!!codeBusy} onclick={()=>googleSignin()}>{ui.continueGoogle}</Button>{/if}{#if config.email}{@render emailForm()}{/if}{@render signInCodeControls()}{/if}<ActionFeedback note={actionNotes['signed-out']}/></section><section class="settings-group" aria-labelledby="connected-apps-heading"><h3 id="connected-apps-heading">{ui.mcpConnectedApps}</h3><p>{ui.mcpConnectedDetail}</p><a href="/connect">{ui.mcpConnectGuide}</a>{#if account}{#if appsLoading}<p role="status">{ui.mcpLoadingApps}</p>{:else if !connectedApps.some(app=>!revokedApps.some(revoked=>revoked.id===app.id))&&!appsError&&!revokedApps.some(app=>actionNotes['revoke-'+app.id])}<p>{ui.mcpNoApps}</p>{/if}{#each connectedApps as app (app.id)}<article class="mcp-app stack" class:revoked-app={revokedApps.some(item=>item.id===app.id)}>{#if !revokedApps.some(item=>item.id===app.id)}<h3>{app.clientName}</h3><small>{ui.mcpConnectedDate(app.connectedAt)}</small><small>{app.lastUsed===null?ui.mcpNeverUsed:ui.mcpLastUsed(app.lastUsed)}</small><ul class="mcp-scopes">{#each app.scope as scope}<li>{ui.mcpScope(scope)}</li>{/each}</ul><Button secondary disabled={!!revoking} onclick={()=>void revokeApp(app)}>{revoking===app.id?ui.mcpRevoking:ui.mcpRevoke}</Button>{/if}<ActionFeedback note={actionNotes['revoke-'+app.id]}/></article>{/each}{#if appsError}<p role="alert">{appsError}</p><Button secondary disabled={appsLoading||!!revoking} onclick={()=>void loadConnectedApps()}>{ui.mcpRetry}</Button>{/if}{/if}</section><section class="settings-group" aria-label={ui.preferences}><label>{ui.displayName}<input bind:value={data.settings.name} onchange={()=>void savePreference('name')} maxlength={80}/></label><ActionFeedback note={actionNotes.name}/><label>{ui.appearance}<select bind:value={data.settings.theme} onchange={(event)=>{data.settings.theme=event.currentTarget.value;stats.trackStats(`theme:${data.settings.theme}`);void savePreference('theme')}}><option value="system">{ui.system}</option><option value="light">{ui.light}</option><option value="dark">{ui.dark}</option></select></label><ActionFeedback note={actionNotes.theme}/><label>{ui.textSize}<select bind:value={data.settings.textSize} onchange={(event)=>{data.settings.textSize=event.currentTarget.value;stats.trackStats(`text_size:${data.settings.textSize}`);void savePreference('textSize')}}>{#each ui.textSizes as [value,label]}<option {value}>{label}</option>{/each}</select></label><ActionFeedback note={actionNotes.textSize}/><label>{ui.defaultTranslation}<select bind:value={data.settings.defaultTranslation} onchange={changeTranslation}>{#each passageTranslations as value}<option>{value}</option>{/each}</select></label><ActionFeedback note={actionNotes.defaultTranslation}/><label>{ui.weeklyRhythm}<select bind:value={data.settings.goal} onchange={()=>void savePreference('goal')}>{#each RULES.rhythmOptions as n}<option value={n}>{ui.weekOption(n)}</option>{/each}</select></label><ActionFeedback note={actionNotes.goal}/><div class="feedback-setting"><div class="feedback-controls"><label class="toggle"><input type="checkbox" bind:checked={data.settings.keySounds} onchange={(event)=>{data.settings.keySounds=event.currentTarget.checked;void savePreference('keySounds')}}/>{ui.keySounds}</label><span role="presentation" onpointerdown={()=>feedback.unlock({keySounds:true})}><button class="text-button" onclick={()=>{feedback.testSound();noteAction('sound',ui.soundTestHelp)}}>{ui.testSound}</button></span></div><small>{ui.soundHelp}</small><ActionFeedback note={actionNotes.sound}/><ActionFeedback note={actionNotes.keySounds}/></div>{#if hapticsSupported}<div class="feedback-setting"><div class="feedback-controls"><label class="toggle"><input type="checkbox" bind:checked={data.settings.haptics} onchange={(event)=>{data.settings.haptics=event.currentTarget.checked;void savePreference('haptics')}}/>{ui.haptics}</label><button class="text-button" disabled={!data.settings.haptics} onclick={()=>noteAction('haptic',ui.hapticTestHelp)}>{ui.testHaptic}</button></div><small>{ui.hapticHelp}</small><ActionFeedback note={actionNotes.haptic}/><ActionFeedback note={actionNotes.haptics}/></div>{/if}<label>{ui.reminderTime}<input type="time" bind:value={data.settings.reminderTime} onchange={()=>void savePreference('reminderTime')}/></label><ActionFeedback note={actionNotes.reminderTime}/><label>{ui.newPerDay}<select bind:value={(data.settings as any).newPerDay} onchange={()=>void savePreference('newPerDay')}>{#each [1,2,3,5] as n}<option value={n}>{n}</option>{/each}</select></label><ActionFeedback note={actionNotes.newPerDay}/><label>{ui.searchZones}<input type="search" placeholder={ui.searchZones} bind:value={zoneSearch}/></label><label>{ui.timeZone}<select bind:value={data.settings.timeZone} onchange={()=>void savePreference('timeZone')}>{#each zones.filter(z=>z===data.settings.timeZone||z.toLowerCase().includes(zoneSearch.toLowerCase())) as zone}<option>{zone}</option>{/each}</select></label><ActionFeedback note={actionNotes.timeZone}/>
 {#if account}<label class="toggle"><input type="checkbox" bind:checked={data.settings.groupShareTitles} onchange={()=>void savePreference('groupShareTitles')}/>{ui.groupShareTitles}</label><ActionFeedback note={actionNotes.groupShareTitles}/><small>{ui.groupShareHelp}</small><label class="toggle"><input type="checkbox" bind:checked={data.settings.groupReceivePrayer} onchange={()=>void savePreference('groupReceivePrayer')}/>{ui.groupReceivePrayer}</label><ActionFeedback note={actionNotes.groupReceivePrayer}/><small>{ui.groupPrayerHelp}</small>{/if}
 </section><section class="settings-group" aria-labelledby="reminder-heading"><h3 id="reminder-heading">{ui.reminders}</h3><p>{ui.reminderInstructions}</p><p>{pushState==='on'?ui.reminderOn:pushState==='missing'?ui.reminderMissing:pushState==='denied'?ui.reminderDenied:pushState==='unsupported'?ui.iosInstallNotice:pushState==='unavailable'?ui.deliveryUnavailable:ui.reminderOff}</p><Button secondary disabled={pushState==='denied'||pushState==='unsupported'} onclick={()=>void (pushState==='on'?disablePush():enablePush())}>{pushState==='on'?ui.disableReminders:pushState==='missing'?ui.turnOnAgain:ui.enableReminders}</Button><ActionFeedback note={actionNotes.reminders}/>{#if pushState==='on'}<Button secondary onclick={()=>void testPush()}>{ui.sendTestPush}</Button><ActionFeedback note={actionNotes['test-push']}/>{/if}<details><summary>{ui.deliveryLog}</summary>{#if deliveries.length}<ul>{#each deliveries as delivery}<li><small>{delivery.time?new Date(delivery.time).toLocaleString():''} · {ui.pushProvider(delivery.host)}</small><p>{ui.pushOutcome(delivery.host,delivery.status,delivery.reason)}</p></li>{/each}</ul>{:else}<p>{ui.deliveryEmpty}</p>{/if}</details>
 </section><section class="settings-group" aria-labelledby="privacy-heading"><h3 id="privacy-heading">{incord.privacy}</h3><label><input type="checkbox" bind:checked={shareCounts} disabled={privacySignal} onchange={event=>void setShareCounts(event)}/>{incord.shareCounts}</label><ActionFeedback note={actionNotes.privacy}/><small>{incord.countsDetail}</small>{#if privacySignal}<small>{incord.privacySignal}</small>{/if}</section><section class="settings-group" aria-label={ui.dataLabel}><Button secondary onclick={()=>void exportData()}>{ui.exportData}</Button><ActionFeedback note={actionNotes.export}/>{#if account}<Button secondary onclick={()=>{clearAction('delete');confirmDelete=true}}>{ui.deleteAccount}</Button>{/if}<ActionFeedback note={actionNotes.deleted}/></section><section class="settings-group" aria-labelledby="send-feedback-heading"><h3 id="send-feedback-heading">{ui.feedbackTitle}</h3><p>{ui.feedbackDetail}</p><form class="stack feedback-form" aria-label={ui.feedbackTitle} novalidate onsubmit={event=>{event.preventDefault();void sendFeedback()}} autocomplete="off">
 <label>{ui.feedbackKind}<select bind:value={feedbackKind} disabled={feedbackBusy} aria-label={ui.feedbackKind}>{#each ui.feedbackKinds as kind}<option>{kind}</option>{/each}</select></label>
 <label>{ui.feedbackMessage}<textarea bind:value={feedbackMessage} minlength={10} maxlength={4000} required disabled={feedbackBusy} aria-describedby="feedback-message-help"></textarea></label><small id="feedback-message-help">{ui.feedbackMessageHelp}</small>
 <label>{ui.feedbackContact}<input name="feedback-reply" type="email" bind:value={feedbackContact} maxlength={254} disabled={feedbackBusy} autocomplete="off" aria-describedby="feedback-contact-help"/></label><small id="feedback-contact-help">{ui.feedbackContactHelp}</small>
 <label class="toggle"><input type="checkbox" bind:checked={feedbackIncludeMeta} disabled={feedbackBusy} aria-describedby="feedback-meta-help"/>{ui.feedbackIncludeMeta}</label><small id="feedback-meta-help">{ui.feedbackMetaHelp}</small>
 <button type="submit" disabled={feedbackBusy} aria-busy={feedbackBusy} class:feedback-sending={feedbackBusy}>{feedbackBusy?ui.feedbackSending:ui.feedbackSend}</button>
 <p aria-live="polite" aria-atomic="true" class:sr-only={!feedbackError&&!feedbackStatus} class="feedback-result" class:feedback-failed={!!feedbackError} bind:this={feedbackResult} role={feedbackError?'alert':feedbackStatus?'status':undefined} tabindex="-1">{feedbackError||feedbackStatus}</p>
 </form></section><section class="settings-group" aria-label={ui.aboutLabel}><h3>{ui.aboutVersion(appVersion)}</h3><small>{ui.aboutApp}</small><EsvAttribution translation={incord.esv} full/><p>{incord.privacyAbout}</p><p>{ui.textSizeAccessibility}</p><a href="/privacy">{incord.privacyPolicy}</a>{#if supportUrl(config.donateUrl)}<a href={supportUrl(config.donateUrl)!} rel="noopener noreferrer">{ui.supportIncord}</a>{/if}</section></div>
 {:else if tab===ui.gallery}<div class="gallery"><Button>{ui.primaryButton}</Button><Button secondary>{ui.secondaryButton}</Button><StepDots step={3}/><WeekDots days={data.settings.days}/><Cover title={ui.gospelTitle} subtitle={ui.galleryVerseCount} color={0} large/><Row title={ui.johnReference} subtitle={ui.galleryStep} translation={ui.bsb}><StepDots step={2}/></Row><VerseText words={[ui.sampleFor,ui.sampleGod,ui.sampleSo,ui.sampleLoved,ui.sampleThe,ui.sampleWorld]} mask={[false,true,false,true,true,false]} index={2}/><Keyboard onkey={()=>{}}/></div>{/if}
 </section><TabBar active={tab} onchange={navigate} pendingRequests={groupAttention?.pendingRequests||0}/>
{/if}
{#if confirmLeavePractice}<Sheet title={ui.leavePracticeTitle} close={()=>confirmLeavePractice=false}><p>{ui.leavePracticeDetail}</p><Button onclick={closePractice}>{ui.leavePractice}</Button><Button secondary onclick={()=>confirmLeavePractice=false}>{ui.keepPracticing}</Button></Sheet>{/if}
{#if jlEmail}<Sheet title={ui.jesklabs.confirmTitle}><p data-private>{ui.jesklabs.continueAs(jlEmail)}</p><Button disabled={jlBusy} onclick={()=>void confirmJl()}>{ui.jesklabs.continue}</Button><Button secondary disabled={jlBusy} onclick={()=>void cancelJl()}>{ui.jesklabs.different}</Button>{#if jlError}<p role="alert">{jlError}</p>{/if}</Sheet>{/if}
{#if awaitingCodeSave}<Sheet title={ui.codeAccount.saveTitle}><p>{ui.codeAccount.saveDetail}</p><p class="signin-code-value" data-private>{deviceCode!.code}</p>{@render codeSaveActions()}<label class="code-save-check"><input type="checkbox" bind:checked={codeSaved}/>{ui.codeAccount.saved}</label><Button disabled={!codeSaved||!!codeBusy} onclick={()=>void finishSavingCode()}>{ui.codeAccount.continue}</Button></Sheet>{/if}
{#if codeConfirm}<Sheet title={codeConfirm==='regenerate'?ui.codeAccount.regenerateTitle:ui.codeAccount.removeTitle} close={()=>{if(!codeBusy)codeConfirm=''}}><p>{codeConfirm==='regenerate'?ui.codeAccount.regenerateDetail:ui.codeAccount.removeDetail}</p><Button disabled={!!codeBusy} onclick={()=>void codeAccountAction(codeConfirm as 'regenerate'|'remove')}>{codeBusy?ui.codeAccount.busy:codeConfirm==='regenerate'?ui.codeAccount.replace:ui.codeAccount.remove}</Button><ActionFeedback note={actionNotes['code-'+codeConfirm]}/><Button secondary disabled={!!codeBusy} onclick={()=>codeConfirm=''}>{ui.codeAccount.cancel}</Button></Sheet>{/if}
{#if confirmDelete}<Sheet title={ui.deleteTitle} close={()=>confirmDelete=false}><p>{ui.deleteInstructions}</p><Button disabled={busy} onclick={()=>void deleteAccount()}>{ui.confirmDelete}</Button><ActionFeedback note={actionNotes.delete}/><Button secondary onclick={()=>confirmDelete=false}>{ui.keepAccount}</Button></Sheet>{/if}
{#if welcome&&!awaitingCodeSave}<Sheet title={ui.welcomeBack} close={()=>welcome=false}><p>{ui.welcomeCount(Math.min(3,live.filter(i=>i.learned).length))}</p><Button onclick={()=>{data.settings.returnStart=today();welcome=false;void save()}}>{ui.start}</Button><Button secondary onclick={()=>{data.settings.returnStart=today();welcome=false;void save();begin(live.filter(i=>i.learned).slice(0,3))}}>{ui.checkMemory}</Button></Sheet>{/if}
{#if preview}<Sheet title={preview.title} close={()=>preview=null}><List>{#each preview.items as item}<Row title={item.title} subtitle={item.text} translation={item.translation}/>{/each}</List><Button onclick={()=>void addStarter(preview)}>{ui.addToMyLibrary}</Button><ActionFeedback note={actionNotes['preview-add']}/>{#if goalTarget&&preview.goalSelection}<Button secondary disabled={groupGoalBusy} onclick={()=>void setGroupGoal(preview.goalSelection)}>{groupGoalBusy?ui.groupGoalSaving:ui.groupGoalUse}</Button>{#if groupGoalError}<p role="alert">{groupGoalError}</p>{/if}{/if}</Sheet>{/if}
{#if removeTarget}<Sheet title={ui.removeTitle} close={()=>removeTarget=null}><p>{ui.removeDetail(removeTarget.title)}</p><Button onclick={()=>void remove(removeTarget!)}>{ui.remove}</Button><ActionFeedback note={actionNotes.remove}/><Button secondary onclick={()=>removeTarget=null}>{ui.keepItem}</Button></Sheet>{/if}

{#if undoItem&&!practice}<div class="undo-toast" role="status">{ui.removed} <button class="text-button" onclick={()=>void undo()}>{ui.undo}</button><ActionFeedback note={actionNotes.undo}/></div>{/if}
{#if confirmBatch}<Sheet title={ui.batchTitle(confirmBatch.length)} close={()=>confirmBatch=null}><Button disabled={busy||batchAdded} onclick={()=>void confirmBatchAdd()}>{batchAdded?ui.added:ui.addItems}</Button><ActionFeedback note={actionNotes['batch-add']}/><Button secondary onclick={()=>confirmBatch=null}>{batchAdded?ui.done:ui.cancel}</Button></Sheet>{/if}
{#if confirmSignout}<Sheet title={ui.signoutTitle} close={()=>confirmSignout=false}><p>{ui.signoutDetail}</p>{@render codeSignoutReminder()}<Button disabled={busy} onclick={()=>void signout()}>{ui.signOut}</Button><ActionFeedback note={actionNotes.signout}/><Button secondary onclick={()=>confirmSignout=false}>{ui.cancel}</Button></Sheet>{/if}
{#if !oauthRoute&&!awaitingCodeSave&&mergePrompt&&!mergeDismissed&&!discardPrompt}<Sheet title={ui.mergeTitle(live.length)} close={()=>mergeDismissed=true}><p>{ui.mergeHistoryDetail}</p><Button onclick={()=>void acceptMerge()}>{ui.mergeAdd}</Button><Button secondary onclick={()=>discardPrompt=true}>{ui.keepSeparate}</Button></Sheet>{/if}
{#if discardPrompt}<Sheet title={ui.discardTitle} close={()=>discardPrompt=false}><p>{ui.discardDetail}</p><Button onclick={()=>void discardLocal()}>{ui.discardLocal}</Button><Button secondary onclick={()=>discardPrompt=false}>{ui.cancel}</Button></Sheet>{/if}
{#if confirmEverywhere}<Sheet title={ui.signoutEverywhereTitle} close={()=>confirmEverywhere=false}><p>{account?.hasCode&&!account?.hasEmail&&!account?.hasGoogle?ui.codeAccount.everywhereDetail:ui.signoutEverywhereDetail}</p>{@render codeSignoutReminder()}<Button disabled={busy} onclick={()=>void signout(true)}>{ui.signoutEverywhere}</Button><ActionFeedback note={actionNotes['signout-everywhere']}/><Button secondary onclick={()=>confirmEverywhere=false}>{ui.cancel}</Button></Sheet>{/if}

</main>
